namespace ghidra.app.plugin.core.datamgr.actions;

using docking.action;
using docking.action;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.util;

public class IncludeDataTypesInFilterAction : ToggleDockingAction {

	private DataTypesProvider provider;

	public IncludeDataTypesInFilterAction(DataTypeManagerPlugin plugin, DataTypesProvider provider,
			string menuSubGroup) : base("Include Data Members in Filter", plugin.getName())
    {
		this.provider = provider;

		setMenuBarData(new MenuData(new string[] { "Include Data Members in Filter" }, null,
			"VeryLast2", MenuData.NO_MNEMONIC, menuSubGroup));
		setDescription(
			"Selected indicates to include member names and data types in filter operations.");

		setEnabled(true);
		setSelected(false); // default to off!

		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Filter"));
	}

	/* @Override */
	public void setSelected(bool newValue) {
		if (isSelected() == newValue) {
			return;
		}
		base.setSelected(newValue);
		provider.setIncludeDataTypeMembersInFilterCallback(newValue);
	}
}
